import { supabaseAdmin } from '@/integrations/supabase/client.server';
import { sendTemplateEmail } from './email-templates/send-email';

export async function sendApplicationNotification(applicationId: string) {
  // The unguessable ID is generated by the submitting browser. Never accept
  // email content or recipients from it, or expose the private row in response.
  const { data, error } = await supabaseAdmin.from('applications')
    .select('id, name').eq('id', applicationId).maybeSingle();
  if (error) throw new Error('Could not verify the application');
  if (!data) return { notified: false };

  const result = await sendTemplateEmail('new-application', '', {
    templateData: { candidateName: data.name },
    idempotencyKey: `new-application-${data.id}`,
  });
  return { notified: result.sent };
}